sys_ui_action.client_script_v2:
(function onClick(g_form) {
    current.state = 'rejected';
    var comments = false;

    var lastComment = current.comments.getJournalEntry(1);
    if (!global.JSUtil.nil(lastComment)) {
        var index = lastComment.indexOf(gs.getUserDisplayName());
        if (index > -1 && index <= 22)
            comments = true;
    }

    if (!global.JSUtil.nil(current.comments) || comments) {
        current.update();
        new global.ApprovalUserFeedback().rejected(current);
    } else {
        gs.addErrorMessage(gs.getMessage("Comments are required when rejecting an approval"));
        current.state = 'requested';
        current.setAbortAction(true);
    }
})(g_form);

